// Demo discovery call notes. PRODUCTION: replace with webhook body from your CRM/form.
const notes = {
  contactName: "Ryan Ellis",
  email: "ryan@redeggmarketing.com",
  company: "Red Egg Marketing",
  process: "client reporting",
  hoursPerWeek: 8,
  hourlyRate: 30,
  volume: 15,
  painPoints: "Reports go out late. Account managers hate writing them. Clients complain about generic insights.",
  industry: "marketing agency"
};
const input = $json.body && $json.body.email ? $json.body : notes;
return { json: { ...input, EventKey: "proposal:" + input.email + ":" + new Date().toISOString().slice(0,10) } };

const n = $json;
const emailOk = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(n.email || ''));
const ok = emailOk && n.company && String(n.company).length >= 2 && (n.hoursPerWeek || 0) > 0;
if (!ok) return { json: { Timestamp: new Date().toISOString(), EventKey: n.EventKey || 'unknown',
  Workflow: 'proposal-generator', Status: 'rejected_invalid_notes', Reason: 'bad email/company/hours' } };
return { json: { ...n, input_valid: true } };

const raw = $json.content?.parts?.filter(p => !p.thought).map(p => p.text || '').join('') ?? $json.text ?? '';
const cleaned = raw.replace(/```json/gi,'').replace(/```/g,'').trim();
let data = null;
for (const c of (cleaned.match(/\{[\s\S]*\}/g) || []).reverse()) {
  try { const p = JSON.parse(c); if (p && p.body) { data = p; break; } } catch(e){}
}
const notes = $('Validate Notes').item.json;
if (!data) return { json: { ...notes, parse_ok: false, error: 'AI output unparseable',
  subject: 'Automation Proposal for ' + notes.company, body: 'Hi ' + notes.contactName + ', thanks for the call. I\'ll send a detailed proposal within 2 days.', confidence: 0.5 } };
const confidence = typeof data.confidence === 'number' ? data.confidence : 0.7;
return { json: { ...notes, ...data, confidence, parse_ok: true } };

